import org.jsoup.Connection;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

public class UrlBuilderTest {

    @Test
    public void buildDefaultUrl() {
        when(new Connection.Builder().build()).thenReturn(new URL("https://example.com"));
        UrlBuilder builder = new UrlBuilder(null);
        URL result = builder.build();
        assertEquals(new URL("https://example.com"), result);
    }

    @Test
    public void buildUrlWithSchemeAndAuthority() {
        when(new Connection.Builder()
                .scheme("https")
                .authority("example.com")
                .build()).thenReturn(new URL("https://example.com"));
        UrlBuilder builder = new UrlBuilder(null);
        URL result = builder.build();
        assertEquals(new URL("https://example.com"), result);
    }

    @Test
    public void buildUrlWithPathAndQuery() throws UnsupportedEncodingException {
        when(new Connection.Builder()
                .scheme("https")
                .authority("example.com")
                .path("/test")
                .query(StringUtil.UTF_8("key=value"))
                .build()).thenReturn(new URL("https://example.com/test?key=value"));
        UrlBuilder builder = new UrlBuilder(null);
        URL result = builder.build();
        assertEquals(new URL("https://example.com/test?key=value"), result);
    }

    @Test
    public void buildUrlWithFragment() throws UnsupportedEncodingException {
        when(new Connection.Builder()
                .scheme("https")
                .authority("example.com")
                .fragment("#anchor")
                .build()).thenReturn(new URL("https://example.com#anchor"));
        UrlBuilder builder = new UrlBuilder(null);
        URL result = builder.build();
        assertEquals(new URL("https://example.com#anchor"), result);
    }

    @Test
    public void appendKeyValNoEncoding() {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        when(new String(kv.getKey())).thenReturn("key");
        when(new String(kv.getValue())).thenReturn("value");
        UrlBuilder builder = new UrlBuilder(null);
        try {
            builder.appendKeyVal(kv);
            fail("Expected UnsupportedEncodingException");
        } catch (UnsupportedEncodingException e) {
            // Expected
        }
    }

    @Test
    public void appendKeyValWithEncoding() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        when(new String(kv.getKey())).thenReturn("key");
        when(new String(kv.getValue())).thenReturn(IDN.toUTF8("value"));
        UrlBuilder builder = new UrlBuilder(null);
        try {
            builder.appendKeyVal(kv);
            fail("Expected UnsupportedEncodingException");
        } catch (UnsupportedEncodingException e) {
            // Expected
        }
    }

    @Test
    public void appendKeyValueWithEncodedValue() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal("key", URLEncoder.encode("value", DataUtil.UTF_8));
        when(new String(kv.getKey())).thenReturn("key");
        when(new String(kv.getValue())).thenReturn(IDN.toUTF8(URLEncoder.encode("value", DataUtil.UTF_8)));
        UrlBuilder builder = new UrlBuilder(null);
        try {
            builder.appendKeyVal(kv);
            fail("Expected UnsupportedEncodingException");
        } catch (UnsupportedEncodingException e) {
            // Expected
        }
    }

